package com.kafka.backend.shareddesk;

import com.kafka.backend.common.CurrentUserProvider;
import com.kafka.backend.shareddesk.storage.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;

/** Owner-serialized, commit-safe mutations; external object I/O never holds the owner lock. */
@Service
public class DeskService {
 final JdbcTemplate db; final CurrentUserProvider users; final ObjectMapper json;
 final TransactionTemplate tx; final ObjectStorage storage; final boolean enabled; final String environment;
 public DeskService(JdbcTemplate db,CurrentUserProvider users,ObjectMapper json,PlatformTransactionManager manager,ObjectStorage storage,
  @Value("${SHARED_DESK_ENABLED:false}") boolean enabled,@Value("${app.db-environment:LOCAL}") String environment){
  this.db=db;this.users=users;this.json=json;this.tx=new TransactionTemplate(manager);this.storage=storage;this.enabled=enabled;this.environment=environment;
 }
 UUID owner(){return users.getCurrentUserId();}
 public Map<String,Object> capabilities(){return Map.of("enabled",enabled,"filesEnabled",enabled&&storage.enabled(),"environment",environment,"ownerId",owner());}
 void gate(){if(!enabled)throw error(503,"FEATURE_DISABLED","공유 작업대가 아직 활성화되지 않았습니다.");}
 void fileGate(){gate();if(!storage.enabled())throw error(503,"STORAGE_UNAVAILABLE","파일 저장소를 사용할 수 없습니다.");}
 static DeskException error(int s,String c,String m){return new DeskException(s,c,m);}
 String encode(Object x){return json.writeValueAsString(x);}
 @SuppressWarnings("unchecked") Map<String,Object> decode(String s){return json.readValue(s,Map.class);}
 static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException();}}
 Object canonical(Object v){if(v instanceof Map<?,?> m){var out=new TreeMap<String,Object>();m.forEach((k,x)->out.put(k.toString(),canonical(x)));return out;}if(v instanceof List<?> l)return l.stream().map(this::canonical).toList();return v;}
 String requestHash(String action,Map<String,Object> body){return hash(action+"\n"+encode(canonical(body)));}
 static UUID uuid(Object value){try{return UUID.fromString(value.toString());}catch(Exception e){throw error(400,"INVALID_ID","올바른 식별자가 필요합니다.");}}
 static long number(Object x){if(!(x instanceof Number n))throw error(400,"INVALID_NUMBER","숫자 형식이 올바르지 않습니다.");return n.longValue();}
 static String text(Object v){if(!(v instanceof String s))throw error(400,"INVALID_TEXT","텍스트를 확인해주세요.");return s;}
 static String body(Object v){String s=text(v);if(s.isEmpty())throw error(400,"EMPTY_BODY","내용을 입력해주세요.");if(s.getBytes(StandardCharsets.UTF_8).length>1048576)throw error(413,"BODY_TOO_LARGE","본문은 UTF-8 기준 1 MiB까지 저장할 수 있습니다.");return s;}
 static String title(Object v,String body){String s=v==null?"":text(v);if(s.isBlank())s=body.lines().filter(x->!x.isBlank()).findFirst().orElse("제목 없음").strip();return s.codePoints().limit(240).collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString();}
 static Instant instant(Object v){if(v instanceof Timestamp t)return t.toInstant();if(v instanceof OffsetDateTime t)return t.toInstant();if(v instanceof Instant t)return t;return Instant.parse(v.toString());}
 List<Map<String,Object>> rows(String sql,Object... args){return db.query(sql,(r,n)->{var m=new LinkedHashMap<String,Object>();var md=r.getMetaData();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));return m;},args);}
 void lock(UUID o){db.update("insert into shared_desk_sync_heads(owner_id) values(?) on conflict(owner_id) do nothing",o);db.queryForObject("select last_seq from shared_desk_sync_heads where owner_id=? for update",Long.class,o);}
 <T>T locked(UUID o,Supplier<T> work){return tx.execute(status->{lock(o);return work.get();});}
 void validOperation(Map<String,Object> b){uuid(b.get("operationId"));try{Instant created=Instant.parse(text(b.get("operationCreatedAt")));if(created.isBefore(Instant.now().minus(Duration.ofDays(30)))||created.isAfter(Instant.now().plusSeconds(300)))throw error(410,"OPERATION_EXPIRED","오래된 전송은 자동 재시도할 수 없습니다. 내용을 확인하고 새로 저장해주세요.");}catch(DeskException e){throw e;}catch(Exception e){throw error(400,"OPERATION_TIME_REQUIRED","operationCreatedAt이 필요합니다.");}}
 Map<String,Object> existing(UUID o,String action,Map<String,Object> b){var list=rows("select * from shared_desk_operations where owner_id=? and operation_id=?",o,uuid(b.get("operationId")));if(list.isEmpty())return null;var old=list.getFirst();if(!old.get("request_hash").equals(requestHash(action,b)))throw error(409,"OPERATION_REUSED","동일 작업 ID의 요청 내용이 바뀌었습니다.");if(instant(old.get("expires_at")).isBefore(Instant.now()))throw error(410,"OPERATION_EXPIRED","작업 기록이 만료되었습니다. 내용을 확인해주세요.");return old.get("result")==null?Map.of("status","VERIFYING"):decode(old.get("result").toString());}
 void saveOperation(UUID o,String action,Map<String,Object>b,Map<String,Object> result){db.update("insert into shared_desk_operations(owner_id,operation_id,request_hash,action,result) values(?,?,?,?,?)",o,uuid(b.get("operationId")),requestHash(action,b),action,encode(result));}
 void finishVerification(UUID o,Object operation,Map<String,Object> result){if(operation!=null)db.update("update shared_desk_operations set result=? where owner_id=? and operation_id=? and result=?",encode(result),o,uuid(operation),encode(Map.of("status","VERIFYING")));}
 Map<String,Object> mutate(String action,Map<String,Object>b,Supplier<Map<String,Object>> work){gate();validOperation(b);UUID o=owner();return locked(o,()->{var old=existing(o,action,b);if(old!=null)return old;var result=work.get();saveOperation(o,action,b,result);return result;});}
 Map<String,Object> raw(UUID o,UUID id){var r=rows("select * from shared_desk_items where owner_id=? and id=?",o,id);if(r.isEmpty())throw error(404,"NOT_FOUND","항목을 찾을 수 없습니다.");return r.getFirst();}
 Map<String,Object> active(UUID o,UUID id,String kind){var r=raw(o,id);if(kind!=null&&!kind.equals(r.get("kind")))throw error(404,"NOT_FOUND","항목을 찾을 수 없습니다.");if(r.get("deleted_at")!=null)throw error(410,"ITEM_DELETED","휴지통으로 이동한 항목입니다.");return r;}
 void revision(Map<String,Object> r,Map<String,Object>b){if(!b.containsKey("expectedRevision"))throw error(428,"REVISION_REQUIRED","expectedRevision이 필요합니다.");if(number(b.get("expectedRevision"))!=number(r.get("revision")))throw new DeskException(409,"REVISION_CONFLICT","다른 기기에서 변경했습니다. 입력한 내용은 보관됩니다.",Map.of("currentRevision",r.get("revision"),"resourceId",r.get("id")));}
 UUID project(UUID o,Object id){if(id==null)return null;UUID p=uuid(id);if(db.queryForObject("select count(*) from projects where id=? and user_id=?",Integer.class,p,o)==0)throw error(404,"PROJECT_NOT_FOUND","프로젝트를 찾을 수 없습니다.");return p;}
 Map<String,Object> fileSummary(UUID o,UUID id){var fs=rows("select * from shared_desk_files where owner_id=? and item_id=?",o,id);if(fs.isEmpty())return Map.of();var f=fs.getFirst();var out=new LinkedHashMap<String,Object>();out.put("displayName",f.get("display_name"));out.put("sizeBytes",f.get("size_bytes"));out.put("sha256",f.get("sha256"));out.put("claimedMime",f.get("claimed_mime"));out.put("state",f.get("state"));out.put("uploadExpiresAt",instant(f.get("upload_expires_at")).toString());return out;}
 Map<String,Object> view(Map<String,Object>r,boolean detail){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","kind","title","pinned","revision"))out.put(k,r.get(k));out.put("projectId",r.get("project_id"));String s=r.get("body").toString();out.put("preview",s.codePoints().limit(180).collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString());if(detail)out.put("body",s);for(String k:List.of("created_at","updated_at","deleted_at"))out.put(switch(k){case "created_at"->"createdAt";case "updated_at"->"updatedAt";default->"deletedAt";},r.get(k)==null?null:instant(r.get(k)).toString());
  if("FILE".equals(r.get("kind")))out.putAll(r.containsKey("file_summary")&&r.get("file_summary")!=null?decode(r.get("file_summary").toString()):fileSummary(uuid(r.get("owner_id")),uuid(r.get("id"))));
  if(detail&&"MEMO".equals(r.get("kind")))out.put("fileIds",db.queryForList("select file_id from shared_desk_memo_files where owner_id=? and memo_id=?",UUID.class,uuid(r.get("owner_id")),r.get("id")));
  return out;}
 long change(UUID o,UUID id,String action){long seq=db.queryForObject("update shared_desk_sync_heads set last_seq=last_seq+1 where owner_id=? returning last_seq",Long.class,o);var r=raw(o,id);db.update("insert into shared_desk_changes(owner_id,seq,entity_id,entity_kind,action,revision) values(?,?,?,?,?,?)",o,seq,id,r.get("kind"),action,r.get("revision"));db.update("insert into shared_desk_item_versions(owner_id,item_id,seq,kind,project_id,title,body,pinned,revision,created_at,updated_at,deleted_at,file_summary) select owner_id,id,?,kind,project_id,title,body,pinned,revision,created_at,updated_at,deleted_at,? from shared_desk_items where owner_id=? and id=?",seq,encode(fileSummary(o,id)),o,id);return seq;}
 void attachments(UUID o,UUID memo,Object value){if(!(value instanceof List<?> ids)||ids.size()>10)throw error(400,"INVALID_ATTACHMENTS","파일 참조는 최대 10개입니다.");var valid=new HashSet<UUID>();for(Object v:ids){UUID id=uuid(v);active(o,id,"FILE");if(!"READY".equals(fileSummary(o,id).get("state")))throw error(409,"FILE_NOT_READY","준비된 파일만 연결할 수 있습니다.");valid.add(id);}db.update("delete from shared_desk_memo_files where owner_id=? and memo_id=?",o,memo);for(UUID id:valid)db.update("insert into shared_desk_memo_files(owner_id,memo_id,file_id) values(?,?,?)",o,memo,id);}
 public Map<String,Object> create(String kind,Map<String,Object>b){if(!Set.of("CLIP","MEMO").contains(kind))throw error(400,"INVALID_KIND","항목 종류가 올바르지 않습니다.");return mutate("CREATE/"+kind,b,()->{UUID o=owner(),id=UUID.randomUUID();String content=body(b.get("body"));db.update("insert into shared_desk_items(id,owner_id,kind,project_id,title,body) values(?,?,?,?,?,?)",id,o,kind,project(o,b.get("projectId")),title(b.get("title"),content),content);if(b.containsKey("fileIds")){if(!kind.equals("MEMO"))throw error(400,"INVALID_ATTACHMENTS","메모에만 파일을 연결할 수 있습니다.");attachments(o,id,b.get("fileIds"));}change(o,id,"UPSERT");return view(raw(o,id),true);});}
 public Map<String,Object> get(String kind,UUID id){gate();return view(active(owner(),id,kind),true);}
 public Map<String,Object> patch(String kind,UUID id,Map<String,Object>b){return mutate("PATCH/"+id,b,()->{UUID o=owner();var r=active(o,id,kind);revision(r,b);String content=b.containsKey("body")?body(b.get("body")):r.get("body").toString();if(kind.equals("FILE")&&b.containsKey("body"))throw error(400,"INVALID_PATCH","파일 본문은 수정할 수 없습니다.");if(b.containsKey("pinned")&&!(b.get("pinned") instanceof Boolean))throw error(400,"INVALID_PATCH","고정 값을 확인해주세요.");db.update("update shared_desk_items set title=?,body=?,pinned=?,project_id=?,revision=revision+1,updated_at=current_timestamp where owner_id=? and id=?",b.containsKey("title")?title(b.get("title"),content):r.get("title"),content,b.getOrDefault("pinned",r.get("pinned")),b.containsKey("projectId")?project(o,b.get("projectId")):r.get("project_id"),o,id);if(b.containsKey("fileIds")){if(!kind.equals("MEMO"))throw error(400,"INVALID_ATTACHMENTS","메모에만 연결할 수 있습니다.");attachments(o,id,b.get("fileIds"));}change(o,id,"UPSERT");return view(raw(o,id),true);});}
 public Map<String,Object> delete(String kind,UUID id,Map<String,Object>b){return mutate("DELETE/"+id,b,()->{UUID o=owner();var r=active(o,id,kind);revision(r,b);if(kind.equals("FILE")&&!"READY".equals(fileSummary(o,id).get("state")))throw error(409,"USE_CANCEL","전송 중인 파일은 취소해주세요.");db.update("update shared_desk_items set deleted_at=current_timestamp,updated_at=current_timestamp,revision=revision+1 where owner_id=? and id=?",o,id);change(o,id,"DELETE");return view(raw(o,id),true);});}
 public Map<String,Object> restore(UUID id,Map<String,Object>b){return mutate("RESTORE/"+id,b,()->{UUID o=owner();var r=raw(o,id);revision(r,b);if(r.get("deleted_at")==null)throw error(409,"NOT_IN_TRASH","휴지통 항목이 아닙니다.");if(instant(r.get("deleted_at")).isBefore(Instant.now().minus(Duration.ofDays(7))))throw error(410,"TRASH_EXPIRED","복구 기간이 지났습니다.");db.update("update shared_desk_items set deleted_at=null,updated_at=current_timestamp,revision=revision+1 where owner_id=? and id=?",o,id);change(o,id,"UPSERT");return view(raw(o,id),true);});}
 public Map<String,Object> operation(UUID id){gate();var list=rows("select * from shared_desk_operations where owner_id=? and operation_id=?",owner(),id);if(list.isEmpty())throw error(404,"NOT_FOUND","작업 기록을 찾을 수 없습니다.");var r=list.getFirst();if(instant(r.get("expires_at")).isBefore(Instant.now()))throw error(410,"OPERATION_EXPIRED","작업 기록이 만료되었습니다.");var result=r.get("result")==null?Map.of("status","VERIFYING"):decode(r.get("result").toString());return Map.of("operationId",id,"status","VERIFYING".equals(result.get("status"))?"PENDING":"ACKNOWLEDGED","result",result);}
 String cursor(UUID o,String purpose,String scope,long high,long position,Duration life){var old=db.queryForList("select token from shared_desk_cursors where owner_id=? and environment=? and purpose=? and scope_hash=? and high_water=? and position=? and expires_at>? limit 1",UUID.class,o,environment,purpose,hash(scope),high,position,Timestamp.from(Instant.now().plus(life.dividedBy(2))));if(!old.isEmpty())return old.getFirst().toString();UUID token=UUID.randomUUID();db.update("insert into shared_desk_cursors(token,owner_id,environment,purpose,scope_hash,high_water,position,expires_at) values(?,?,?,?,?,?,?,?)",token,o,environment,purpose,hash(scope),high,position,Timestamp.from(Instant.now().plus(life)));return token.toString();}
 Map<String,Object> readCursor(UUID o,String token,String purpose,String scope){var list=rows("select * from shared_desk_cursors where token=? and owner_id=? and environment=? and purpose=? and scope_hash=?",uuid(token),o,environment,purpose,hash(scope));if(list.isEmpty())throw error(400,"INVALID_CURSOR","현재 계정·필터의 커서가 아닙니다.");var r=list.getFirst();if(instant(r.get("expires_at")).isBefore(Instant.now()))throw error(410,"CURSOR_EXPIRED","동기화 커서가 만료되었습니다. 초안을 유지하고 새로고침해주세요.");return r;}
 long high(UUID o){Long n=db.queryForObject("select coalesce((select last_seq from shared_desk_sync_heads where owner_id=?),0)",Long.class,o);return n==null?0:n;}
 public Map<String,Object> list(String kind,String q,UUID projectId,boolean unlinked,String token,int limit,boolean trash){gate();if(limit<1||limit>100||q.length()>240||projectId!=null&&unlinked)throw error(400,"INVALID_FILTER","검색 조건을 확인해주세요.");UUID o=owner();String scope=kind+"/"+q+"/"+projectId+"/"+unlinked+"/"+trash;return tx.execute(s->{long high=high(o),offset=0;if(token!=null){var c=readCursor(o,token,"LIST",scope);high=number(c.get("high_water"));offset=number(c.get("position"));}var args=new ArrayList<Object>();args.add(o);args.add(high);String sql="select v.*,v.item_id as id,case when p.id is null then null else v.project_id end as project_id from shared_desk_item_versions v left join projects p on p.id=v.project_id and p.user_id=v.owner_id where v.owner_id=? and v.seq=(select max(v2.seq) from shared_desk_item_versions v2 where v2.owner_id=v.owner_id and v2.item_id=v.item_id and v2.seq<=?)";if(!kind.equals("ALL")){sql+=" and v.kind=?";args.add(kind);}sql+=trash?" and v.deleted_at is not null and v.deleted_at>current_timestamp-interval '7 days'":" and v.deleted_at is null";if(!q.isEmpty()){sql+=" and (position(lower(?) in lower(v.title))>0 or position(lower(?) in lower(v.body))>0)";args.add(q);args.add(q);}if(projectId!=null){sql+=" and p.id=?";args.add(projectId);}if(unlinked)sql+=" and p.id is null";sql+=" order by v.pinned desc,v.seq desc,v.item_id desc limit ? offset ?";args.add(limit+1);args.add(offset);var items=rows(sql,args.toArray());boolean more=items.size()>limit;if(more)items=items.subList(0,limit);var out=new LinkedHashMap<String,Object>();out.put("items",items.stream().map(r->view(r,false)).toList());out.put("hasMore",more);out.put("nextCursor",more?cursor(o,"LIST",scope,high,offset+limit,Duration.ofHours(1)):null);return out;});}
 public Map<String,Object> changes(String after,String until,int limit){gate();if(limit<1||limit>200)throw error(400,"INVALID_LIMIT","페이지 크기를 확인해주세요.");UUID o=owner();return tx.execute(s->{long h=high(o),a=h;if(after!=null){a=number(readCursor(o,after,"CHANGE","").get("position"));}if(until!=null){h=number(readCursor(o,until,"CHANGE","").get("position"));if(h<a)throw error(400,"INVALID_CURSOR","동기화 범위를 확인해주세요.");}long floor=db.queryForObject("select coalesce((select retention_floor from shared_desk_sync_heads where owner_id=?),0)",Long.class,o);if(a<floor)throw error(410,"CURSOR_EXPIRED","변경 기록 보존 기간이 지났습니다. 초안을 유지하고 전체 목록을 다시 불러와주세요.");var rs=rows("select seq,entity_id,entity_kind,action,revision from shared_desk_changes where owner_id=? and seq>? and seq<=? order by seq limit ?",o,a,h,limit+1);boolean more=rs.size()>limit;if(more)rs=rs.subList(0,limit);long next=more?number(rs.getLast().get("seq")):h;var changes=rs.stream().map(r->Map.of("seq",r.get("seq"),"entityId",r.get("entity_id"),"entityKind",r.get("entity_kind"),"action",r.get("action"),"revision",r.get("revision"))).toList();return Map.of("changes",changes,"hasMore",more,"highWater",cursor(o,"CHANGE","",h,h,Duration.ofDays(30)),"nextCursor",cursor(o,"CHANGE","",h,next,Duration.ofDays(30)));});}
 public List<Map<String,Object>> replies(UUID parent){gate();UUID o=owner();active(o,parent,"MEMO");return rows("select * from shared_desk_replies where owner_id=? and parent_id=? order by created_at,id limit 200",o,parent).stream().map(r->{var out=new LinkedHashMap<String,Object>();out.put("id",r.get("id"));out.put("parentId",r.get("parent_id"));out.put("body",r.get("body"));out.put("revision",r.get("revision"));out.put("createdAt",instant(r.get("created_at")).toString());out.put("updatedAt",instant(r.get("updated_at")).toString());return (Map<String,Object>)out;}).toList();}
 public Map<String,Object> reply(UUID parent,Map<String,Object>b){return mutate("REPLY/"+parent,b,()->{UUID o=owner();active(o,parent,"MEMO");UUID id=UUID.randomUUID();String content=body(b.get("body"));db.update("insert into shared_desk_replies(id,owner_id,parent_id,body) values(?,?,?,?)",id,o,parent,content);db.update("update shared_desk_items set revision=revision+1,updated_at=current_timestamp where owner_id=? and id=?",o,parent);long seq=change(o,parent,"UPSERT");db.update("update shared_desk_replies set change_seq=? where owner_id=? and id=?",seq,o,id);return Map.of("id",id,"parentId",parent,"body",content,"revision",1,"createdAt",Instant.now().toString(),"updatedAt",Instant.now().toString());});}
 public Map<String,Object> replyPage(UUID parent,String token,int limit){gate();if(limit<1||limit>100)throw error(400,"INVALID_LIMIT","페이지 크기를 확인해주세요.");UUID o=owner();active(o,parent,"MEMO");String scope="REPLY/"+parent;return tx.execute(t->{long h=high(o),position=0;if(token!=null){var c=readCursor(o,token,"REPLY",scope);h=number(c.get("high_water"));position=number(c.get("position"));}var rs=rows("select * from shared_desk_replies where owner_id=? and parent_id=? and change_seq<=? order by created_at,id limit ? offset ?",o,parent,h,limit+1,position);boolean more=rs.size()>limit;if(more)rs=rs.subList(0,limit);var result=new LinkedHashMap<String,Object>();result.put("items",rs.stream().map(r->Map.of("id",r.get("id"),"parentId",parent,"body",r.get("body"),"revision",r.get("revision"),"createdAt",instant(r.get("created_at")).toString(),"updatedAt",instant(r.get("updated_at")).toString())).toList());result.put("hasMore",more);result.put("nextCursor",more?cursor(o,"REPLY",scope,h,position+limit,Duration.ofHours(1)):null);return result;});}
 public Map<String,Object> usage(){gate();UUID o=owner();var states=rows("select state,count(*) as count,coalesce(sum(size_bytes),0) as bytes from shared_desk_files where owner_id=? group by state",o);long retained=db.queryForObject("select coalesce(sum(size_bytes),0) from shared_desk_files where owner_id=? and (state='READY' or (state='VERIFYING' and final_key is not null))",Long.class,o)+db.queryForObject("select coalesce(sum(size_bytes),0) from shared_desk_upload_reservations where owner_id=?",Long.class,o);long estimated=db.queryForObject("select coalesce((select download_bytes_estimate from shared_desk_sync_heads where owner_id=?),0)",Long.class,o);int cleanup=db.queryForObject("select count(*) from shared_desk_object_cleanup where owner_id=? and attempts>0",Integer.class,o);return Map.of("states",states,"retainedBytes",retained,"quotaBytes",1073741824L,"maxFileBytes",104857600L,"downloadBytesEstimate",estimated,"downloadWarning",estimated>=10737418240L,"cleanupFailures",cleanup,"trashDays",7);}
}
